		"event-calendar-do-2",
		'1import\u001f0 \u001f1type\u001f0 { CalendarEvent, EventCalendarTone } \u001f1from\u001f0 \u001f4"@workspace/ui-kit-logic"\u001f0;\n1import\u001f0 { EventCalendar } \u001f1from\u001f0 \u001f4"@workspace/ui-native/components/event-calendar"\u001f0;\n1import\u001f0 \u001f3*\u001f0 \u001f1as\u001f0 React \u001f1from\u001f0 \u001f4"react"\u001f0;\n1import\u001f0 { View } \u001f1from\u001f0 \u001f4"react-native"\u001f0;\n\n1import\u001f0 { atHour, SAMPLE_CLOCK, ToneLegend } \u001f1from\u001f0 \u001f4"./event-calendar-sample"\u001f0;\n\n1const\u001f0 \u001f3LEGEND\u001f1:\u001f0 \u001f1readonly\u001f0 { \u001f1readonly\u001f0 \u001f7tone\u001f1:\u001f0 \u001f2EventCalendarTone\u001f0; \u001f1readonly\u001f0 \u001f7label\u001f1:\u001f0 \u001f3string\u001f0 }[] \u001f1=\u001f0 [\n0\t{ tone: \u001f4"green"\u001f0, label: \u001f4"Occupied"\u001f0 },\n0\t{ tone: \u001f4"red"\u001f0, label: \u001f4"Check-out"\u001f0 },\n0];\n1const\u001f0 \u001f3EVENTS\u001f1:\u001f0 \u001f1readonly\u001f0 \u001f2CalendarEvent\u001f0[] \u001f1=\u001f0 [\n0\t{ id: \u001f4"a"\u001f0, title: \u001f4"Reed"\u001f0, start: \u001f2atHour\u001f0(\u001f32\u001f0, \u001f30\u001f0), end: \u001f2atHour\u001f0(\u001f34\u001f0, \u001f30\u001f0), allDay: \u001f3true\u001f0, color: \u001f4"green"\u001f0 },\n0\t{ id: \u001f4"b"\u001f0, title: \u001f4"Reed"\u001f0, start: \u001f2atHour\u001f0(\u001f34\u001f0, \u001f30\u001f0), end: \u001f2atHour\u001f0(\u001f35\u001f0, \u001f30\u001f0), allDay: \u001f3true\u001f0, color: \u001f4"red"\u001f0 },\n0];\n\n5// The colours carry a meaning, and the legend says which.\n1export\u001f0 \u001f1function\u001f0 \u001f2EventCalendarDo2Example\u001f0()\u001f1:\u001f0 \u001f2React\u001f0.\u001f2JSX\u001f0.\u001f2Element\u001f0 {\n0\t\u001f1return\u001f0 (\n0\t\t<\u001f3View\u001f0 \u001f2className\u001f1=\u001f4"w-full gap-3"\u001f0>\n0\t\t\t<\u001f3EventCalendar\u001f0 \u001f2events\u001f1=\u001f0{\u001f3EVENTS\u001f0} \u001f2defaultView\u001f1=\u001f4"month"\u001f0 \u001f2clock\u001f1=\u001f0{\u001f3SAMPLE_CLOCK\u001f0} \u001f2showNav\u001f1=\u001f0{\u001f3false\u001f0} />\n0\t\t\t<\u001f3ToneLegend\u001f0 \u001f2entries\u001f1=\u001f0{\u001f3LEGEND\u001f0} />\n0\t\t</\u001f3View\u001f0>\n0\t);\n0}',
